function tokenize(pattern) {
  const tokens = [];
  let i = 0;
  while (i < pattern.length) {
    const ch = pattern[i];
    if (ch === '\\') {
      if (i + 1 >= pattern.length) throw new SyntaxError('the pattern ends with a backslash');
      tokens.push({ kind: 'char', ch: pattern[i + 1] });
      i += 2;
      continue;
    }
    if (ch === '*') {
      let stars = 0;
      while (pattern[i] === '*') {
        stars += 1;
        i += 1;
      }
      tokens.push({ kind: stars > 1 ? 'globstar' : 'star' });
      continue;
    }
    if (ch === '?') {
      tokens.push({ kind: 'any' });
      i += 1;
      continue;
    }
    if (ch === '[') {
      let j = i + 1;
      let negated = false;
      if (pattern[j] === '!') {
        negated = true;
        j += 1;
      }
      const members = [];
      if (pattern[j] === ']') {
        members.push({ from: ']', to: ']' });
        j += 1;
      }
      for (;;) {
        if (j >= pattern.length) throw new SyntaxError('a character class was never closed');
        if (pattern[j] === ']') break;
        const from = pattern[j];
        if (pattern[j + 1] === '-' && j + 2 < pattern.length && pattern[j + 2] !== ']') {
          members.push({ from, to: pattern[j + 2] });
          j += 3;
          continue;
        }
        members.push({ from, to: from });
        j += 1;
      }
      tokens.push({ kind: 'class', negated, members });
      i = j + 1;
      continue;
    }
    tokens.push({ kind: 'char', ch });
    i += 1;
  }
  return tokens;
}

function inClass(token, ch) {
  let hit = false;
  for (const member of token.members) {
    if (ch >= member.from && ch <= member.to) {
      hit = true;
      break;
    }
  }
  return token.negated ? !hit : hit;
}

export function matchGlob(pattern, path) {
  if (typeof pattern !== 'string') throw new TypeError('pattern must be a string');
  if (typeof path !== 'string') throw new TypeError('path must be a string');

  const tokens = tokenize(pattern);
  const p = tokens.length;
  const s = path.length;
  const width = s + 1;
  // can[i * width + j] is true when tokens.slice(i) matches path.slice(j).
  // The table makes the search linear in p * s, so a wildcard-heavy mismatch
  // cannot take exponential time.
  const can = new Uint8Array((p + 1) * width);
  can[p * width + s] = 1;

  for (let i = p - 1; i >= 0; i -= 1) {
    const token = tokens[i];
    for (let j = s; j >= 0; j -= 1) {
      const ch = j < s ? path[j] : null;
      let ok = 0;
      if (token.kind === 'star') {
        ok = can[(i + 1) * width + j] || (ch !== null && ch !== '/' && can[i * width + j + 1]);
      } else if (token.kind === 'globstar') {
        ok = can[(i + 1) * width + j] || (ch !== null && can[i * width + j + 1]);
      } else if (ch === null) {
        ok = 0;
      } else if (token.kind === 'any') {
        ok = ch !== '/' && can[(i + 1) * width + j + 1];
      } else if (token.kind === 'class') {
        ok = ch !== '/' && inClass(token, ch) && can[(i + 1) * width + j + 1];
      } else {
        ok = ch === token.ch && can[(i + 1) * width + j + 1];
      }
      can[i * width + j] = ok ? 1 : 0;
    }
  }

  return can[0] === 1;
}
